from collections import Counter
import json
def archive_diff(a,b):
 left=a['members'];right=b['members'];x=[s for s in left if s['is_cgu']];y=[s for s in right if s['is_cgu']];names=lambda l:[s['name'] for s in l];h=lambda l:[s['sha256'] for s in l];assert len(x)==len(y);pairs=list(zip(x,y));g=set(k for p in pairs for ms in p for k in ms.get('section_content_digests',{}));return {'producer_library_hashes':[a['sha256'],b['sha256']],'members':[len(left),len(right)],'cgu_objects':[len(x),len(y)],'equal_member_name_per_cgu_slot':sum(l['name']==r['name'] for l,r in pairs),'equal_complete_object_bytes_per_cgu_slot':sum(l['sha256']==r['sha256'] for l,r in pairs),'same_cgu_object_payload_multiset':Counter(h(x))==Counter(h(y)),'all_ordered_object_bytes_equal':h(x)==h(y),'per_section_group_differences':{k:sum(l.get('section_content_digests',{}).get(k)!=r.get('section_content_digests',{}).get(k) for l,r in pairs) for k in sorted(g)},'total_source_basename_hits_in_raw_debug_bytes':[sum(p.get('debug_source',{}).get('input_path_occurrences',0) for p in x),sum(p.get('debug_source',{}).get('input_path_occurrences',0) for p in y)],'total_source_md5_in_raw_debug_bytes':{k:[sum(p.get('debug_source',{}).get('changed_source_file_md5',{}).get(k,0) for p in x),sum(p.get('debug_source',{}).get('changed_source_file_md5',{}).get(k,0) for p in y)] for k in ('original','edited')},'non_cgu_changed':[{'before':l['name'],'after':r['name'],'equal':l['sha256']==r['sha256']} for l,r in zip([s for s in left if not s['is_cgu']],[s for s in right if not s['is_cgu']])],'index_and_name_tables_equal':[l==r for l,r in zip(a['index_and_names'],b['index_and_names'])],'ordered_cgu_names_sha256_before':__import__('hashlib').sha256('\n'.join(names(x)).encode()).hexdigest(),'ordered_cgu_names_sha256_after':__import__('hashlib').sha256('\n'.join(names(y)).encode()).hexdigest()}
